def longest_subseq_with_diff_one(arr, n):
    # This function finds the longest subsequence where the difference between adjacent elements is exactly 1
    # We use dynamic programming to solve this problem
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)
