def triangle_area(a, b, c):
    # Check if the three sides can form a valid triangle
    if a + b > c and a + c > b and b + c > a:
        # Calculate the area using Heron's formula
        s = (a + b + c) / 2
        area = s * (s - a) * (s - b) * (s - c)
        return round(area, 2)
    else:
        return -1
