def find_minimum_range(arrays):
    # Sort each array
    sorted_arrays = [sorted(arr) for arr in arrays]

    # Find the minimum and maximum elements
    min_val = min(sorted_arrays[0][0])
    max_val = max(sorted_arrays[-1][-1])

    # Find the smallest range that includes at least one element from each array
    start = min_val
    end = max_val

    # Find the smallest range by checking each element
    while True:
        found = False
        for i in range(len(sorted_arrays)):
            for j in range(len(sorted_arrays[i])):
                if sorted_arrays[i][j] > start and sorted_arrays[i][j] < end:
                    start = sorted_arrays[i][j]
                    found = True
                    break
            if found:
                break
        if not found:
            break

    return (start, end)
```

