def is_valid_parenthese(s):
    stack = []
    for char in s:
        if char == '(' or char == '[' or char == '{':
            stack.append(char)
        elif char == ')' or char == ']' or char == '}':
            if not stack:
                return False
            if stack[-1] == '(' and char == ')':
                stack.pop()
            elif stack[-1] == '[' and char == ']':
                stack.pop()
            elif stack[-1] == '{' and char == '}':
                stack.pop()
    return len(stack) == 0
