def do_algebra(operator, operand):
    """Given two lists operator, and operand. The first list has basic algebra operations, and the second list is a list of integers. Use the two given lists to build the algebric expression and return the evaluation of this expression."""
    # Convert operator to a list of operations
    operations = [op for op in operator]

    # Convert operand to a list of integers
    operand_list = [int(num) for num in operand]

    # Perform the algebraic expression
    result = operand_list[0]
    for i in range(1, len(operand_list)):
        if operations[i] == '+':
            result += operand_list[i]
        elif operations[i] == '-':
            result -= operand_list[i]
        elif operations[i] == '*':
            result *= operand_list[i]
        elif operations[i] == '//':
            result = result // operand_list[i]
        elif operations[i] == '**':
            result = result ** operand_list[i]

    return result
