def shell_sort(arr):
    n = len(arr)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            j = i - gap
            if arr[j] > arr[i]:
                arr[j], arr[i] = arr[i], arr[j]
        gap //= 2
