    right = ")]}"
    stack = []
    for char in s:
        if char in left:
            stack.append(char)
        elif char in right:
            if not stack:
                return False
            top = stack.pop()
            if (char, top) in [("}", ")"] or (char, left) in [("(", "{"]):
                continue
            else:
                return False
    return len(stack) == 0
