def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for l in range(2, n + 1):
        for i in range(n - l + 1):
            j = i + l - 1
            dp[i][j] = dp[i + 1][j - 1] + (1 if s[i] == s[j] else 0)
    return dp[0][n - 1]
