def sum_common_divisors(a, b):
    # Find the greatest common divisor
    gcd = a
    while gcd % b != 0:
        gcd = a // b
    # Find all common divisors
    divisors = set()
    for i in range(1, gcd + 1):
        if a % i == 0 and b % i == 0:
            divisors.add(i)
    return sum(divisors)
